// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes4 constant IACCESS_CONTROL_ID = 0x7965db0b;
    bytes4 constant IERC165_ID = 0x01ffc9a7;

    function setUp() public { c = new C(0, address(this), address(this)); }

    function testFuzz_property(bytes4 interfaceId) public {
        // Ensure we only test the IAccessControl ID to show the difference
        vm.assume(interfaceId == IACCESS_CONTROL_ID);

        bool result = c.supportsInterface(interfaceId);
        assertTrue(result, "supportsInterface should return true for IAccessControl");
    }
}

