pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        delay = bound(delay, c.getMinDelay(), type(uint256).max - block.timestamp);
        vm.assume(value <= address(this).balance);
        address target = address(this);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        c.schedule(target, value, data, predecessor, salt, delay);
        c.cancel(id);
        assertTrue(c.supportsInterface(type(IAccessControl).interfaceId));
    }
}

