import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id, address sender) public {
        vm.assume(sender == address(this)); // Only the deployer can call cancel
        (bool ok, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", id));
        if (ok) {
            assertTrue(c.supportsInterface(type(IAccessControl).interfaceId));
        } else {
