pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        // Ensure the caller has PROPOSER_ROLE (by default, msg.sender in setup is the contract deployer)
        vm.assume(c.hasRole(c.PROPOSER_ROLE(), address(this)));

        // Schedule an operation to make cancel valid
        // We need a valid operation to schedule. Use a dummy target and data.
        // But the function signature is schedule(target, value, data, predecessor, salt, delay)
        // To simplify, we skip scheduling and only test cancel when the operation is pending.
        // However, we cannot assume a state; so we use try/catch to handle revert.

        // Attempt to cancel
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.cancel.selector, id));
        if (success) {
            // If cancel succeeded, then the operation must not be pending
            assertTrue(!c.isOperationPending(id));
        } else {
            // If cancel reverts, we don't need to assert anything about the return value of isOperationPending
            assertTrue(true);
        }
    }
}

