pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address caller, bool isPending) public {
        vm.assume(caller != address(this));

        // Create a dummy operation to potentially schedule
        bytes32 dummyId = keccak256("dummy");

        if (isPending) {
            // We need to schedule an operation to make it pending
            // But schedule requires PROPOSER_ROLE; the contract deployer has it
            address target = address(0);
            uint256 value = 0;
            bytes memory data = "";
            bytes32 salt = 0;
            uint256 delay = 1;
            c.schedule(target, value, data, bytes32(0), salt, delay);
            dummyId = c.hashOperation(target, value, data, bytes32(0), salt);
        }

        // Try to cancel as caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", dummyId));

        // Rule: cancel should revert if caller does not have PROPOSER_ROLE or operation is not pending
        bool callerHasProposerRole = c.hasRole(c.PROPOSER_ROLE(), caller);
        assertTrue(success == (callerHasProposerRole && isPending), "cancel() should only succeed for proposer with pending operation");
    }
}

