pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(!c.hasRole(c.PROPOSER_ROLE(), caller));

        // First schedule an operation to make it pending
        bytes32 salt = keccak256(abi.encode(id, caller));
        bytes32 opId = c.hashOperation(address(0), 0, "", bytes32(0), salt);

        // Schedule as proposer
        vm.prank(address(this));
        c.schedule(address(0), 0, "", bytes32(0), salt, 1 days);

        // Now try to cancel as a non-proposer
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", opId));

        // The rule: cancel should revert for non-proposers
        assertTrue(!success);
    }
}

