pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address caller, address target, uint256 value, bytes memory data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        vm.assume(caller != address(0) && caller != address(this));
        vm.assume(delay >= 0);
        vm.assume(data.length <= 256);

        // Schedule an operation
        if (c.hasRole(c.PROPOSER_ROLE(), address(this))) {
            c.schedule(target, value, data, predecessor, salt, delay);
        }

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 timestampBefore = c.getTimestamp(id);

        // Attempt cancel as caller
        vm.prank(caller);
        (bool ok,) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", id));

        uint256 timestampAfter = c.getTimestamp(id);

        // Rule: If cancel succeeded (ok is true), then timestamp must be 0.
        // If cancel failed (ok is false), timestamp must remain unchanged.
        assertTrue((ok && timestampAfter == 0) || (!ok && timestampAfter == timestampBefore));
    }
}

