        // However, since address(this) might already be the default admin (sender in constructor), we can directly grant.
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        // Now schedule the operation
        c.schedule(address(0), 0, "", bytes32(0), id, 0);
        // Now cancel the operation
        (bool cancelSuccess,) = address(c).call(abi.encodeWithSelector(c.cancel.selector, id));
        // The cancel should succeed only if the operation is pending. Since we just scheduled it, it is pending.
        // After cancel, check isOperationPending for that id.
        bool pendingAfterCancel = c.isOperationPending(id);
        // The reference ensures that after cancel, the operation is not pending (timestamp deleted or set to 0).
        assertTrue(!pendingAfterCancel);
    }
}

