pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    function testFuzz_property(bytes32 id, uint256 offset) public {
        // offset is the time to wait after scheduling until the operation becomes ready
        // Bound offset to [0, 1000] to keep test reasonable
        offset = bound(offset, 0, 1000);

        // Schedule the operation with delay = 0 to make its timestamp = block.timestamp
        // We need to use the PROPOSER_ROLE (address(this) has it from setup)
        vm.warp(block.timestamp + 1); // advance time to avoid collision with previous timestamps
        c.schedule(address(this), 0, hex"", bytes32(0), id, 0);

        // Now the operation's timestamp = block.timestamp after schedule
        // Wait offset blocks (warp to that timestamp)
        vm.warp(block.timestamp + offset);

        // The operation should be ready iff block.timestamp >= timestamp (and timestamp > 1)
        // In the reference, ready when timestamp <= block.timestamp
        // With offset = 0, timestamp == block.timestamp, so ready in reference, not in mutant
        bool isReady = c.isOperationReady(id);

        // General rule: when offset == 0, the operation must be ready (timestamp == block.timestamp)
        // For offset > 0, it also must be ready, but we focus on the boundary
        // We assert: if block.timestamp >= timestamp (i.e., offset >= 0), then ready is true
        // Since we always have offset >= 0 (by construction), ready must be true
        assertTrue(isReady, "Operation should be ready when block.timestamp >= timestamp");
    }
}

