    function testFuzz_property(bytes32 salt, uint256 delay, address target, uint256 value, bytes memory data, bytes32 predecessor) public {
        vm.assume(delay >= 0 && delay <= 365 days);
        vm.assume(predecessor == bytes32(0));

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Schedule the operation
        c.schedule(target, value, data, predecessor, salt, delay);

        // Attempt to cancel before the operation is ready
        bool reverted;
        try c.cancel(id) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The operation is not yet ready, so cancel must revert
        assertTrue(reverted, "cancel should revert when operation not ready");
    }
}

