pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 salt, uint256 value, bytes memory data, bytes32 predecessor, uint256 delay) public {
        vm.assume(delay >= 0 && delay <= 1000000);
        vm.assume(value <= address(this).balance);
        // Schedule an operation
        c.schedule(address(this), value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(address(this), value, data, predecessor, salt);
        // Cancel the operation
        c.cancel(id);
        // After cancel, getTimestamp should return 0
        assertTrue(c.getTimestamp(id) == 0);
    }
}
